"""Legacy user config DTO conversion and user and auto-generated file processor calls."""

from ai.backend.common.data.entity.user import UserID
from ai.backend.common.data.filter_specs import StringMatchSpec
from ai.backend.common.dotfile import DotfilePath
from ai.backend.common.dto.manager.config.response import (
    CreateDotfileResponse,
    DeleteDotfileResponse,
    DotfileListItem,
    GetDotfileResponse,
    UpdateDotfileResponse,
)
from ai.backend.manager.data.auto_generated_file.types import AutoGeneratedFileData
from ai.backend.manager.data.dotfile.types import DotfileEntry
from ai.backend.manager.dto.user_config_input import (
    CreateAutoGeneratedFileInput,
    DeleteDefaultAutoGeneratedFileInput,
    UpdateDefaultAutoGeneratedFileInput,
)
from ai.backend.manager.errors.storage import DotfileNotFound
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.searchable_fields import (
    AutoGeneratedFileSearchableFields,
)
from ai.backend.manager.models.auto_generated_file.searchers import AutoGeneratedFileSearcher
from ai.backend.manager.models.auto_generated_file.updaters import AutoGeneratedFileUpdater
from ai.backend.manager.models.specs.pagination import NoPagination
from ai.backend.manager.services.auto_generated_file.actions.purge import (
    PurgeAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.actions.search import (
    SearchAutoGeneratedFilesAction,
)
from ai.backend.manager.services.auto_generated_file.actions.update import (
    UpdateAutoGeneratedFileAction,
)
from ai.backend.manager.services.auto_generated_file.processors import AutoGeneratedFileProcessors
from ai.backend.manager.services.user.actions.create_auto_generated_file import (
    CreateAutoGeneratedFileAction,
)
from ai.backend.manager.services.user.processors import UserProcessors


class UserConfigAdapter:
    _user: UserProcessors
    _auto_generated_file: AutoGeneratedFileProcessors

    def __init__(
        self, user: UserProcessors, auto_generated_file: AutoGeneratedFileProcessors
    ) -> None:
        self._user = user
        self._auto_generated_file = auto_generated_file

    async def _search_default_auto_generated_files(
        self, user_id: UserID, path: str | None = None
    ) -> list[AutoGeneratedFileData]:
        fields = AutoGeneratedFileSearchableFields.own
        conditions = [fields.is_default.filter.equals(True)]
        if path is not None:
            conditions.append(
                fields.path.filter.equals(
                    StringMatchSpec(value=path, case_insensitive=False, negated=False)
                )
            )
        result = await self._auto_generated_file.search.run(
            SearchAutoGeneratedFilesAction(
                user_ids=[user_id],
                searcher=AutoGeneratedFileSearcher(
                    pagination=NoPagination(),
                    conditions=conditions,
                    orders=[fields.created_at.order.apply(True), fields.field_id.order.apply(True)],
                ),
            )
        )
        return result.items

    async def create_auto_generated_file(
        self, input: CreateAutoGeneratedFileInput
    ) -> CreateDotfileResponse:
        await self._user.create_auto_generated_file.run(
            CreateAutoGeneratedFileAction(
                creator=AutoGeneratedFileCreator(
                    owner=input.user_id,
                    entry=DotfileEntry(path=input.path, perm=input.perm, data=input.data),
                ),
            )
        )
        return CreateDotfileResponse()

    async def get_default_auto_generated_file(
        self, user_id: UserID, path: str
    ) -> GetDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(user_id, path)
        if not auto_generated_files:
            raise DotfileNotFound
        auto_generated_file = auto_generated_files[0]
        return GetDotfileResponse(
            path=auto_generated_file.path,
            perm=auto_generated_file.perm,
            data=auto_generated_file.data,
        )

    async def get_default_auto_generated_files(self, user_id: UserID) -> list[DotfileListItem]:
        auto_generated_files = await self._search_default_auto_generated_files(user_id)
        return [
            DotfileListItem(path=d.path, permission=d.perm, data=d.data)
            for d in auto_generated_files
        ]

    async def update_default_auto_generated_file(
        self, input: UpdateDefaultAutoGeneratedFileInput
    ) -> UpdateDotfileResponse:
        DotfilePath(input.path)
        auto_generated_files = await self._search_default_auto_generated_files(
            input.user_id, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        await self._auto_generated_file.update.run(
            UpdateAutoGeneratedFileAction(
                updater=AutoGeneratedFileUpdater(
                    auto_generated_file_id=auto_generated_files[0].id,
                    perm=input.perm,
                    data=input.data,
                )
            )
        )
        return UpdateDotfileResponse()

    async def delete_default_auto_generated_file(
        self, input: DeleteDefaultAutoGeneratedFileInput
    ) -> DeleteDotfileResponse:
        auto_generated_files = await self._search_default_auto_generated_files(
            input.user_id, input.path
        )
        if not auto_generated_files:
            raise DotfileNotFound
        await self._auto_generated_file.purge.run(
            PurgeAutoGeneratedFileAction(auto_generated_file_id=auto_generated_files[0].id)
        )
        return DeleteDotfileResponse(success=True)
